     4	final class BellmanFord {
     5	
     6	    private BellmanFord() {}
     7	
     8	    static ShortestPathResult shortestPaths(WeightedGraph graph, int source) {
     9	        int V = graph.vertices();
    10	        if (source < 0 || source >= V) {
    11	            throw new IllegalArgumentException(
    12	                "Source vertex " + source + " is out of range [0," + (V - 1) + "]");
    13	        }
    14	
    15	        EdgeRelaxer relaxer = new EdgeRelaxer(V, source);
    16	        List<WeightedEdge> edges = graph.edges();
    17	
    18	        for (int i = 0; i < V - 1; i++) {
    19	            for (WeightedEdge e : edges) {
    20	                relaxer.relax(e);
    21	            }
    22	        }
    23	
    24	        Optional<NegativeCycle> cycle =
    25	            new NegativeCycleDetector(relaxer, edges, V).detect();
    26	
    27	        return cycle.isPresent()
    28	            ? cycle.get()
    29	            : new Distances(source, relaxer.distances(), relaxer.predecessors());
    30	    }
    31	}
